#!/usr/bin/env node
// pnpm run generate            write src/generated/*.ts from tau-core's templates
// pnpm run check-generated     exit 1 when a generated file is stale (CI)
//
// tau-host keeps model ids, prices and the default persona as data taken from tau-core
// (ADR 0013 §2), never as hand-written copies:
//
//   packages/tau-core/src/tau_core/templates/models.toml  -> src/generated/models.ts
//   packages/tau-core/src/tau_core/templates/prices.toml  -> src/generated/prices.ts
//   packages/tau-core/src/tau_core/templates/persona.md   -> src/generated/persona.ts
//
// Each generated file also carries the SHA-256 of its source, which a vitest compares
// with the template it imports, so a stale file fails the tests as well.
//
// The TOML reader below takes exactly the subset these two files use (comments, [table] and
// ["quoted table"] headers, string, number and boolean values) and fails on anything else,
// so a richer template is noticed here instead of being misread.

import { createHash } from "node:crypto";
import { mkdirSync, readFileSync, writeFileSync } from "node:fs";
import { dirname, join, relative } from "node:path";
import { fileURLToPath } from "node:url";

const root = join(dirname(fileURLToPath(import.meta.url)), "..");
const templates = join(root, "..", "..", "packages", "tau-core", "src", "tau_core", "templates");
const out = join(root, "src", "generated");
const check = process.argv.includes("--check");

/** The value of one TOML scalar, or an error naming the line. */
function scalar(raw, where) {
  const text = raw.trim();
  if (text.startsWith('"')) {
    let value = "";
    let i = 1;
    for (; i < text.length; i++) {
      const c = text[i];
      if (c === '"') break;
      if (c === "\\") {
        const next = text[++i];
        const escapes = { n: "\n", t: "\t", r: "\r", '"': '"', "\\": "\\" };
        if (!(next in escapes)) throw new Error(`${where}: unsupported escape \\${next}`);
        value += escapes[next];
      } else {
        value += c;
      }
    }
    if (i >= text.length) throw new Error(`${where}: unterminated string`);
    const rest = text.slice(i + 1).trim();
    if (rest !== "" && !rest.startsWith("#")) throw new Error(`${where}: text after the value`);
    return value;
  }
  const bare = text.split("#")[0].trim();
  if (bare === "true") return true;
  if (bare === "false") return false;
  if (/^[+-]?[0-9][0-9_]*(\.[0-9_]+)?([eE][+-]?[0-9]+)?$/.test(bare)) {
    return Number(bare.replaceAll("_", ""));
  }
  throw new Error(`${where}: unsupported value ${JSON.stringify(bare)}`);
}

/** `{table: {key: value}}` from the TOML subset described above. */
export function parseToml(text, name) {
  const tables = {};
  let current = null;
  text.split("\n").forEach((line, index) => {
    const where = `${name}:${index + 1}`;
    const trimmed = line.trim();
    if (trimmed === "" || trimmed.startsWith("#")) return;
    const header = /^\[\s*(?:"([^"]+)"|([A-Za-z0-9_-]+))\s*\]\s*(#.*)?$/.exec(trimmed);
    if (header) {
      const table = header[1] ?? header[2];
      if (Object.hasOwn(tables, table)) throw new Error(`${where}: duplicate table ${table}`);
      tables[table] = current = {};
      return;
    }
    const pair = /^([A-Za-z0-9_-]+)\s*=\s*(.+)$/.exec(trimmed);
    if (!pair) throw new Error(`${where}: not a table header or a key = value line`);
    if (current === null) throw new Error(`${where}: a key outside any table`);
    current[pair[1]] = scalar(pair[2], where);
  });
  return tables;
}

function sha256(text) {
  return createHash("sha256").update(text, "utf8").digest("hex");
}

function header(source) {
  return [
    `// Generated by \`pnpm run generate\` from ${source}. Do not edit:`,
    "// change the template in tau-core and run the generator again.",
    "",
  ].join("\n");
}

function renderModels(text) {
  const tables = parseToml(text, "models.toml");
  for (const [provider, roles] of Object.entries(tables)) {
    for (const role of ["brain", "fast"]) {
      if (typeof roles[role] !== "string") {
        throw new Error(`models.toml: [${provider}] has no string ${role}`);
      }
    }
  }
  return (
    header("packages/tau-core/src/tau_core/templates/models.toml") +
    "\n/** The model ids tau picks for the brain and fast roles of each provider. */\n" +
    `export const MODELS: Readonly<Record<string, { readonly brain: string; readonly fast: string }>> = ${JSON.stringify(tables, null, 2)};\n` +
    `\nexport const MODELS_SOURCE_SHA256 = "${sha256(text)}";\n`
  );
}

function renderPrices(text) {
  const tables = parseToml(text, "prices.toml");
  for (const [model, price] of Object.entries(tables)) {
    for (const [key, value] of Object.entries(price)) {
      if (!["input", "output", "cache_read", "cache_write"].includes(key)) {
        throw new Error(`prices.toml: ["${model}"] has an unknown key ${key}`);
      }
      if (typeof value !== "number" || value < 0) {
        throw new Error(`prices.toml: ["${model}"].${key} must be a non-negative number`);
      }
    }
    if (price.input === undefined || price.output === undefined) {
      throw new Error(`prices.toml: ["${model}"] needs input and output`);
    }
  }
  return (
    header("packages/tau-core/src/tau_core/templates/prices.toml") +
    "\nexport interface Price {\n  readonly input: number;\n  readonly output: number;\n  readonly cache_read?: number;\n  readonly cache_write?: number;\n}\n" +
    "\n/** US dollars per million tokens, by model id (ADR 0011). */\n" +
    `export const PRICES: Readonly<Record<string, Price>> = ${JSON.stringify(tables, null, 2)};\n` +
    `\nexport const PRICES_SOURCE_SHA256 = "${sha256(text)}";\n`
  );
}

function renderPersona(text) {
  return (
    header("packages/tau-core/src/tau_core/templates/persona.md") +
    "\n/** tau's default persona, as tau-core ships it (HTML comments are stripped at use). */\n" +
    `export const DEFAULT_PERSONA = ${JSON.stringify(text)};\n` +
    `\nexport const PERSONA_SOURCE_SHA256 = "${sha256(text)}";\n`
  );
}

const jobs = [
  ["models.toml", "models.ts", renderModels],
  ["prices.toml", "prices.ts", renderPrices],
  ["persona.md", "persona.ts", renderPersona],
];

let stale = 0;
mkdirSync(out, { recursive: true });
for (const [source, target, render] of jobs) {
  const text = readFileSync(join(templates, source), "utf8");
  const wanted = render(text);
  const path = join(out, target);
  let current = null;
  try {
    current = readFileSync(path, "utf8");
  } catch {
    current = null;
  }
  const shown = relative(root, path);
  if (current === wanted) {
    if (!check) console.log(`${shown} is up to date.`);
    continue;
  }
  if (check) {
    console.error(`${shown} is stale: run \`pnpm run generate\` in cloud/host and commit it.`);
    stale++;
  } else {
    writeFileSync(path, wanted);
    console.log(`Wrote ${shown}.`);
  }
}
if (check && stale === 0) console.log("The generated files match tau-core's templates.");
process.exit(stale > 0 ? 1 : 0);
